    [1952] = "의식이 끝나면 타베사와 대화하십시오.",
    [2040] = "죽음의 폐광에서 노암 톱니구동장치를 찾아 스톰윈드에 있는 쇼니에게 가져가야 합니다.",
    [2198] = "부서진 목걸이의 잠재적 가치를 알아내기 위해 원 제작자를 찾아야 합니다.",
    [2199] = "아이언포지에 있는 탈바쉬 델 키젤에게 은괴 5개를 가져가야 합니다.",
    [2200] = "울다만 안에서 탈바쉬의 목걸이의 행방에 대한 단서를 찾아야 합니다. 탈바쉬가 말했던 성기사가 그 단서를 가진 최후의 인물일 것입니다.",
    [2201] = "울다만에 흩어져 있는 루비, 사파이어, 토파즈를 찾아야 합니다. 모두 찾으면 탈바쉬가 준 수정점 유리병을 사용하여 그에게 연락해야 합니다.$B$B일지에 의하면...$B*루비는 어둠괴철로단 드워프들이 있는 지역에 숨겨져 있습니다.$B*토파즈는 얼라이언스 드워프들이 있는 곳 근처에 트로그 지역에 있는 항아리 중 하나에 숨겨져 있습니다.$B$B*사파이어는 트로그 대장인 그림로크가 가지고 있습니다.",
    [2202] = "카르가스에 있는 자칼 모스멜드에게 자홍버섯 12개를 가져가야 합니다.",
    [2204] = "울다만에서 가장 강력한 피조물을 찾아 부서진 목걸이의 마력원천을 손에 넣은 다음, 아이언포지에 있는 탈바쉬 델 키젤에게 목걸이와 함께 가져가야 합니다.",
    [2240] = "밸로그의 일지를 읽고 비밀 석실을 조사한 후 발굴조사단장 스톰파이크에게 보고해야 합니다.",
    [2278] = "바위감시자와 대화하고 그가 알고 있는 고대의 지식을 배우십시오. 지식을 배운 후에는 노르간논의 원반을 가동하십시오.",
    [2279] = "아이언포지에 있는 탐험가 연맹에 노르간논의 소형 백금 원반을 가져가야 합니다.",
    [2280] = "썬더 블러프에 있는 현자 중 하나에게 노르간논의 소형 원반을 가져가야 합니다.",
    [2283] = "울다만 발굴 현장에서 값진 목걸이를 찾아 오그리마에 있는 드란 드로퍼스에게 가져다주어야 합니다. 목걸이는 파손된 것이라도 괜찮습니다.",
    [2284] = "울다만 깊은 곳에서 보석의 행방에 대한 단서를 찾아야 합니다.",
    [2318] = "성기사의 일지를 번역할 수 있는 이를 찾아야 합니다. 그런 자가 있을만한 가장 가까운 곳은 황야의 땅에 있는 카르가스입니다.",
    [2338] = "자칼에게 목걸이를 빌려주면 그에 대한 보답으로 일지를 번역해 줄 것입니다.",
    [2339] = "울다만에서 목걸이에 필요한 보석 3개와 마력원천을 회수한 후 카르가스에 있는 자칼 모스멜드에게 가져다주어야 합니다. 자칼의 말에 의하면 울다만에서 가장 강한 피조물을 처치하면 마력원천을 얻을 수 있다고 합니다.$B$B일지의 내용을 보니 루비는 어둠괴철로단의 방어진에 숨겨져 있습니다.$B$B토파즈는 얼라이언스 드워프 근처에 있는 트로그 구역 중 하나에 있는 항아리에 숨겨져 있습니다.$B$B사파이어는 트로그의 우두머리인 그림로크가 가지고 있습니다.$B$B마력원천은 울다만에서 가장 강한 피조물을 처치하면 얻을 수 있습니다.",
    [2340] = "오그리마에 있는 드란 드로퍼스에게 회수한 목걸이와 보석을 가져다주어야 합니다.",
    [2341] = "카르가스에 있는 자칼 모스멜드를 만나 그의 실험이 성공했는지 알아보십시오.",
    [2342] = "울다만의 남쪽 대전당에 있는 궤짝에서 가레트가의 보물을 찾아 언더시티에 있는 그에게 가져가야 합니다.",
    [2359] = "데피아즈단 탑 열쇠를 훔쳐 데피아즈단 탑으로 숨어 들어간 후, 그늘숲 궤짝에 무엇이 들어 있는지 밝혀 내야 합니다. 알아낸 모든 정보를 가지고 스톰윈드에 있는 마티아스 쇼에게 돌아가야 합니다. 켈넌의 보고서을 읽고 탑에 대한 정보를 얻으십시오.",
    [2360] = "서부 몰락지대로 가서 첩보원 켈넌을 찾아 보고를 받아야 합니다.",
    [2361] = "이 목걸이를 기꺼이 당신에게 주겠소. 당신은 나에게 헤아릴 수 없이 귀중한 일을 해 주었소. 정말 고맙소이다. 자, 자랑스럽게 걸고 다니시오. 그리고 누가 만든 것인지 크게, 그리고 많이 말해 주시오!$B$B실제로 목걸이가 저주받지 않았다는 사실도 곁들여주면 더 고맙겠군.",
    [2398] = "울다만에서 밸로그를 찾아야 합니다.",
    [2418] = "황야의 땅에 있는 리글퍼즈에게 덴트리움 마법석 8개와 안알레움 마법석 8개를 가져가야 합니다.",
    [2439] = "아이언포지 은행에 있는 디니타 스톤맨틀에게 사례 보증 서류를 가져가야 합니다.",
    [2440] = "썬더 블러프에 있는 베나 윈터후프에게 사례 보증 서류를 가져가야 합니다.",
    [2458] = "진흙 늪 북쪽에 있는 투자개발회사 탑으로 가서 검은손 도적단의 비밀 요원인 감독관 피줄과 접촉해야 합니다.$B$B탑이 보이면 섬광탄포를 사용해 감독관 피줄에게 당신이 도착했음을 알리십시오. 섬광탄은 2번 발사해야 하며, 그 후 감독관 피줄에게 다가가 검은손 도적단 /경례를 해야 합니다.$B$B피줄은 자기가 모르는 자는 무조건 처치하려 들기 때문에 정확한 순서대로 수행해야 합니다.",
    [2460] = "셴툴에게 검은손 도적단 /경례를 해 보이십시오.",
    [2478] = "현장감독 실릭시즈에게서 실릭시즈의 탑 열쇠를 훔쳐낸 다음, 돌연변이 투자개발회사 일꾼 2명과 투자개발회사 순찰대원 2명, 그리고 투자개발회사 망꾼 2명을 처치해야 합니다.$B$B총감독 갤리윅스를 암살하고 그의 머리카락을 손에 넣은 후, 갤리윅스의 금고를 열고 잔질의 변화된 혼합물을 훔쳐내야 합니다. 그 혼합물과 갤리윅스의 머리카락을 오그리마에 있는 셴툴에게 가져다주고 다음 지시를 받으십시오.",
    [2479] = "힐스브래드 구릉지의 타렌 밀농장으로 가서 서지 히노트에게 잔질의 혼합물 견본을 전해야 합니다.$B$B타렌 밀농장으로 가려면 먼저 비행선을 타고 언더시티로 가야 합니다. 도착하면 남쪽 길을 따라 은빛소나무 숲을 지나 힐스브래드 쪽으로 가야 합니다. 표지판을 따라 가십시오!",
    [2480] = "서지 히노트가 해독제를 만드는 동안 기다려야 합니다.",
    [2607] = "병영 지하실에 있는 닥 믹실픽실과 대화해야 합니다.",
    [2608] = "닥 믹실픽실에게 검사를 받으려면 \"/누워\"야 합니다. 믹실픽실은 원인도 모르는 병의 치료법을 어떻게 찾을 수 있을까요?",
    [2609] = "닥 믹실픽실에게 수수한 야생화, 가연 약병 1개, 청동관 1개, 그리고 밝은 황록색 비단 실타래 1개를 가져가야 합니다. '그것'은 저절로 낫지 않는 병인 것 같습니다.",
    [2621] = "스토나드에 있는 파견사령관 루아그와 대화하십시오.",
    [2622] = "벤고르와 대화하십시오.",
