    [3001] = "톱니항에 있는 스트라드 파선을 찾아가야 합니다.",
    [3042] = "가젯잔에 있는 트렌튼 라이트해머에게 트롤 경화제 20병을 가져가야 합니다.",
    [3141] = "로라무스 탈리뻬데스의 이야기를 들으십시오.",
    [3369] = "장로의 봉우리에 있는 하뮬 룬토템에게 악몽의 조각을 가져가야 합니다.",
    [3370] = "다르나서스에 있는 마스렌길 베어워커에게 악몽의 조각을 가져가야 합니다.",
    [3373] = "가라앉은 사원의 이 안식처에 있는 정수의 샘에 에라니쿠스의 정수를 놓아야 합니다.",
    [3380] = "타나리스에서 마본 리벳시커를 찾아야 합니다.",
    [3446] = "슬픔의 늪에 있는 가라앉은 사원에서 학카르 제단을 찾아야 합니다.",
    [3447] = "가라앉은 사원으로 가서 원 모양으로 서 있는 석상들에 감춰진 비밀을 알아내야 합니다.",
    [3504] = "아즈샤라에 있는 아그토르 블러드피스트에게 아그토르에게 보내는 봉인된 편지를 전해야 합니다.",
    [3505] = "블러드 엘프 수색병 6명과 블러드 엘프 감정관 6명을 처치한 후, 림토리의 힘의 근원을 밝혀내야 합니다.",
    [3508] = "로라무스가 깨우침의 마법을 마칠 때까지 기다려야 합니다.",
    [3509] = "아즈샤라에 있는 제왕 아크코로크와 대화해야 합니다. 아크코란의 신전을 찾으려면 물가부터 조사해 보십시오.",
    [3510] = "헤타에라를 물리치고 헤타에라의 훼손된 머리, 헤타에라의 피묻은 머리, 헤타에라의 으깨진 머리를 제왕 아크코로크에게 가지고 가야 합니다.",
    [3511] = "헤타에라의 피를 로라무스 탈리뻬데스에게 가져가야 합니다.",
    [3520] = "페랄라스에 있는 3마리의 계곡천둥매의 영혼을 모은 후 스팀휘들 항구에 있는 예킨야에게 돌아가야 합니다.",
    [3527] = "타나리스에 있는 예킨야에게 첫번째 모쉬아루 서판과 두번째 모쉬아루 서판을 가져가야 합니다.",
    [3528] = "타나리스에 있는 예킨야에게 충만한 학카르의 알을 가져가야 합니다.",
    [3602] = "아즈샤라 남부 지역에서 결정화된 아즈샤리트 20개를 회수해야 합니다. 교묘하게 숨겨져 있는 아즈샤리트의 위치는 지옥사냥개에게 냄새를 맡게 해서 찾을 수 있습니다.",
    [3621] = "가시덤불 골짜기에 있는 갈반에게 상자를 가져가야 합니다.",
    [3625] = "갈반이 무기를 다 만들 때까지 기다려야 합니다.",
    [3626] = "호드 영웅의 넋에게 돌아가야 합니다.",
    [3627] = "파괴자 그롤, 여군주 세바인, 대마법사 알리스타즈를 해치우고 그들의 시체에서 그롤의 아뮬렛, 세바인의 아뮬렛, 알리스타즈의 아뮬렛을 회수해야 합니다.$B$B마력이 깃든 아즈샤리트 퇴마 무기를 사용하여 3인조의 힘을 약화시켜야 그들을 처치할 수 있다는 것을 명심하십시오. 반드시 현명하게 사용해야 합니다.",
    [3628] = "파멸자 라젤리크를 해치우고 파멸자의 부러진 뿔을 호드 영웅의 넋에게 가져가야 합니다. 파멸자의 수호물도 호드 영웅의 넋에게 돌려주어 파괴하도록 해야 합니다. 그래야 사악한 자들의 손에 들어가는 것을 막을 수 있습니다.",
    [3631] = "불모의 땅에 있는 스트라드 파선과 대화하십시오.",
    [3701] = "불타는 평원, 타우릿산의 폐허에 있는 타우릿산 유물에서 정보를 얻어야 합니다. 정보를 발견하면 왕실사학자 아케소누스에게 돌아가야 합니다.",
    [3702] = "왕실사학자 아케소누스가 들려 주는 타우릿산의 역사를 들어야 합니다.",
    [3783] = "두꺼운 설인 모피 10개를 모아 눈망루 마을에 있는 우미 럼플스니커에게 갖다주어야 합니다.",
    [3801] = "도시 주요 지역으로 통하는 열쇠를 얻고 싶다면 프랑클론 포지라이트와 대화하십시오.",
    [3802] = "파이너스 다크바이어를 처치하고 거대한 망치, 무쇠지옥을 회수해야 합니다. 무쇠지옥을 타우릿산의 제단으로 가져가서 프랑클론 포지라이트의 석상에 두어야 합니다.",
    [3844] = "연못을 둘러보고 이 난파된 나룻배의 주인에 대한 단서를 찾아야 합니다.",
    [3845] = "가방 안에 든 물건을 조사해 그 주인에게 되돌려주어야 합니다.",
    [3903] = "밀리 오스워드와 대화해야 합니다.",
    [3904] = "노스샤이어 수도원에 있는 밀리 오스워드에게 밀리의 수확물 8 상자를 가져가야 합니다.",
    [3907] = "검은바위 나락에 들어가 불의군주 인센디우스를 찾아, 그를 처치한 후 얻게 되는 모든 정보를 썬더하트에게 가져가야 합니다.",
    [3908] = "여명의 설원에 있는 도노바 스노우덴에게 링쿠의 훈련용 검을 가져가야 합니다.",
    [3909] = "페랄라스 북쪽에서 그레간 브루스퓨를 찾아야 합니다. 그에게서 앞날의 비약을 얻는 방법을 배워 여명의 설원에 있는 도노바 스노우덴에게 돌아가야 합니다.",
    [3912] = "가젯잔 밖에 있는 무덤으로 가서 앞날의 비약을 사용하십시오. 도노바의 지시에 따라 개리얀을 찾아야 합니다.",
    [3913] = "부활한 후, 개리얀이 말한 묘비를 찾아야 합니다.",
    [3914] = "운고로 분화구에 있는 링쿠에게 링쿠의 명검을 가져가야 합니다.",
    [3941] = "마샬의 야영지에 있는 동굴에서 J.D. 콜리를 찾아야 합니다.",
    [3942] = "악령의 숲 남부에 있는 에리단 블루윈드를 찾아가야 합니다.",
    [3961] = "마샬의 야영지에 있는 링쿠에게 아쿠에멘타스의 은토템을 가져가야 합니다.",
    [3962] = "마샬의 야영지 남쪽에 있는 불기둥 마루로 가야 합니다.$B$B불바람을 찾아 토템을 이용해 오라를 제거하십시오. 정령을 물리친 후, 동굴에서 황금 불길을 손에 넣어야 합니다.",
    [3981] = "검은바위 나락에서 사령관 고르샤크를 찾아야 합니다.$B$B조잡하게 그려진 오크 그림에 쇠창살이 그려져 있던 것이 생각납니다. 감옥 같은 곳을 찾아봐야 할 것 같습니다.",
    [3982] = "고르샤크를 보호해야 합니다.",
    [4001] = "카란 마이트해머와 대화하여 공주 모이라 브론즈비어드의 납치에 대한 정보를 모은 후, 그 정보를 오그리마에 있는 스랄에게 가져가야 합니다.$B$B고르샤크가 카란이 근처 감방에 갇혀 있다고 말했던 것이 기억납니다.",
    [4002] = "스랄이 계획한 임무를 맡을 준비가 되었으면 스랄과 다시 한번 대화하십시오.",
    [4003] = "제왕 다그란 타우릿산을 처치하고 그의 사악한 마법에서 공주 모이라 브론즈비어드를 해방시켜야 합니다.",
    [4004] = "스랄에게 돌아가야 합니다!",
    [4005] = "아쿠오르의 책, 은백색 발톱, 그리고 강철나무 심장을 가지고 타나리스로 가십시오.$B$B아쿠오르의 책을 사용해 아쿠에멘타스를 소환해야 합니다.$B$B토템을 완성하면 마샬의 야영지에 있는 J.D. 콜리에게 가져가야 합니다.",
    [4024] = "검은바위 나락으로 가서 밸가르를 처치하십시오.$B$B이 거인이 검은바위 나락 내에 살고 있다는 것만 알고 있으며 밸가르의 시체에 변형된 검은용군단 허물을 사용해 불의 정수를 추출해야만 합니다.$B$B키루스 테레펜터스에게 담겨진 불의 정수를 가져가야 합니다.",
    [4063] = "골렘 군주 아젤마크를 찾아 처치하고 그 증거로 그의 머리카락을 로트윌에게 가져가야 합니다. 그리고 아젤마크를 호위하는 재앙의 피조물과 맹위의 전투골렘들에게서 온전한 원소핵 10개도 모아야 합니다.",
    [4081] = "검은바위 나락으로 가서 사악한 침략자들을 쳐부수십시오!$B$B장군 고어투스가 성난모루단 보초 15명, 성난모루단 교도관 10명, 성난모루단 보병 5명을 처치해 달라고 부탁했습니다. 임무를 완수하면 장군 고어투스에게 돌아가십시오.",
    [4082] = "검은바위 나락으로 가서 사악한 침략자들을 쳐부수십시오!$B$B장군 고어투스가 성난모루단 간호병 10명, 성난모루단 병사 10명, 그리고 성난모루단 장교 10명을 처치해 달라고 부탁했습니다. 임무를 완수하면 고어투스에게 돌아가십시오.",
    [4083] = "유령의 성배가 마치 죽어가는 심장의 고동에 맞추어 춤을 추듯이 천천히 움직이면서 공중에 떠다닙니다.",
    [4084] = "악령의 숲에 있는 에리단 블루윈드에게 은백색 발톱 11개와 강철나무 심장 1개를 가져가야 합니다.",
    [4121] = "포로인 그랄크 로크럽을 호송해 불타는 평원을 지나고 검은바위 산을 넘어 이글거리는 협곡으로 가야 합니다.$B$B반대편에서 렉스로트의 부하들이 기다리다가 그랄크 로크럽을 인계받도록 하겠다고 렉스로트가 말했던 것이 기억납니다.$B$B또한 토륨 족쇄를 렉스로트에게 전해주어야 합니다.",
    [4122] = "불타는 평원으로 가서 그랄크 로크럽을 찾아야 합니다. 렉스로트가 그를 마지막으로 거대한 검은바위 요새에서 보았다고 말했던 것이 기억납니다.$B$B그랄크 로크럽을 찾으면 토륨 족쇄를 사용해 그를 포박한 뒤 다시 검은바위 산을 지나 이글거리는 협곡으로 데려가야 합니다. 렉스로트의 부하들이 반대편에서 기다리고 있다가 그랄크를 인계받을 것입니다.",
    [4123] = "불타는 평원에 있는 맥스워트 우버글린트에게 산의 정수를 가져가야 합니다.",
    [4124] = "페더문 요새에 있는 긴로 하트킨들과 대화해야 합니다.",
    [4125] = "페랄라스 해안에서 안내원의 배를 찾아야 합니다.",
    [4126] = "카라노스에 있는 라그나르 썬더브루에게 잃어버린 썬더브루 제조법을 가져가야 합니다.",
    [4127] = "페더문 요새로 돌아가 긴로 하트킨들에게 잃어버린 나이프를 보여주어야 합니다.",
    [4128] = "라그나르 썬더브루와 대화해야 합니다.",
    [4129] = "페더문 요새에 있는 쿠인티스 존스피레에게 잃어버린 나이프를 가져가야 합니다.",
    [4130] = "페더문 요새에 있는 긴로 하트킨들과 대화해야 합니다.",
    [4131] = "페랄라스 남부에 있는 덩굴발일족 놀 야영지를 수색해 안내원이나 그의 소지품에 대한 증거를 찾아야 합니다.",
    [4132] = "검은바위 나락으로 가서 사령관 앵거포지를 처치한 후 장군 고어투스에게 돌아가야 합니다.",
    [4133] = "카르가스에 있는 비비안 라그레이브와 대화해야 합니다.",
    [4134] = "카르가스에 있는 비비안 라그레이브에게 잃어버린 썬더브루 제조법을 가져가야 합니다.",
    [4135] = "라스칼의 마지막 행방을 알아냈으니 고통의 구덩이에서 그를 찾아야 합니다. 그의 쪽지에 따르면 고통의 구덩이는 덩굴발일족 놀 야영지의 남쪽에 있습니다.",
    [4136] = "리블리를 처치하고 그 증거로 그의 머리카락을 불타는 평원에 있는 유카 스크류스피곳에게 가져가야 합니다.",
    [4182] = "검은 새끼용 15마리, 검은용혈족 10마리, 검은고룡족 4마리와 검은 비룡 1마리를 처치한 후, 헬렌디스 리버혼에게 돌아가야 합니다.",
    [4183] = "레이크샤이어로 가서 집정관 솔로몬에게 헬렌디스 리버혼의 편지를 전달해야 합니다.",
    [4184] = "스톰윈드로 가서 대영주 볼바르 폴드라곤에게 볼바르에게 보내는 솔로몬의 탄원서를 전해주어야 합니다.$B$B볼바르는 스톰윈드 왕궁에 있습니다.",
    [4185] = "여군주 카트라나 프레스톨과 얘기를 나눈 후, 대영주 볼바르 폴드라곤과 대화하십시오.",
    [4186] = "레이크샤이어에 있는 집정관 솔로몬에게 볼바르의 명령서를 가져가야 합니다.",
    [4201] = "검은바위 나락에 있는 여왕 나그마라에게 그롬의 피 4개, 거대한 은 광석 10개, 가득 찬 나그마라의 약병을 가져가야 합니다.",
    [4223] = "불타는 평원에 있는 치안대장 맥스웰과 대화하십시오.",
    [4224] = "털보 존을 만나 치안대장 윈저의 행방에 대해서 알아낸 다음 치안대장 맥스웰에게 돌아가 보고해야 합니다.$B$B치안대장 맥스웰은 북쪽에 있는 동굴에서 털보 존을 찾아보라고 했습니다.",
    [4241] = "북서쪽에 있는 검은바위 산으로 가서 검은바위 나락으로 들어가십시오. 치안대장 윈저에게 무슨 일이 있었는지 알아내야 합니다.$B$B털보 존은 윈저가 감옥으로 끌려갔다고 했습니다.",
    [4242] = "치안대장 맥스웰에게 나쁜 소식을 전해줘야 합니다.",
    [4263] = "검은바위 나락에서 불의군주 인센디우스를 찾아 처치해야 합니다.",
    [4264] = "방금 우연히 치안대장 윈저가 보고 싶어할 듯한 물건을 찾은 것 같습니다. 어쩌면 희망이 있을지도 모릅니다.",
    [4265] = "주크애쉬 소굴에서 라스칼을 풀어줘야 합니다.$B$B페더문 요새에 있는 긴로 하트킨들에게 돌아가 라스칼이 무사히 살아 있다는 소식을 전해 주십시오.",
    [4266] = "페더문 요새에 있는 샨드리스 페더문과 대화해야 합니다.",
    [4267] = "다르나서스에 있는 그라시나 스피릿마이트에게 라스칼의 보고서를 가져가야 합니다.",
    [4281] = "탈라나르에 있는 팔핀델 웨이워더에게 배달되지 않은 꾸러미를 가져가야 합니다.",
    [4282] = "치안대장 윈저의 잃어버린 단서를 가져 와야 합니다.$B$B치안대장 윈저는 골렘 군주 아젤마크와 사령관 앵거포지가 이 정보를 가지고 있을 것이라 생각합니다.",
    [4286] = "검은바위 나락으로 가서 검은무쇠 부족 벨트주머니 20개를 얻어야 합니다. 이 임무를 완수하면 랄리우스에게 돌아가십시오. 검은바위 나락 안에 사는 검은무쇠 드워프들이 이 '벨트주머니'라는 물건을 지니고 다닐 것입니다.",
    [4322] = "치안대장 윈저가 자신의 장비를 되찾고 갇힌 동료들을 풀어 주는 것을 도와야 합니다. 성공하면 치안대장 맥스웰에게 돌아가십시오.",
    [4324] = "불타는 평원에 있는 유카 스크류스피곳과 대화해야 합니다.",
    [4341] = "검은바위 나락으로 가서 카란 마이트해머를 찾아야 합니다.$B$B국왕은 카란이 그곳에 포로로 잡혀 있을 것이라고 말했습니다. 그곳 감옥을 찾아보는 것이 좋겠습니다.",
    [4342] = "카란 마이트해머가 하는 이야기를 들어야 합니다.",
    [4361] = "아이언포지로 돌아가 국왕 마그니 브론즈비어드에게 이 나쁜 소식을 전해야 합니다.",
    [4362] = "검은바위 나락으로 돌아가 제왕 다그란 타우릿산의 사악한 손아귀에서 공주 모이라 브론즈비어드를 구출해야 합니다.",
    [4363] = "아이언포지로 돌아가서 국왕 마그니 브론즈비어드와 대화해야 합니다.",
    [4487] = "톱니항에 있는 스트라드 파선과 대화하십시오.",
    [4488] = "톱니항에 있는 스트라드 파선과 대화하십시오.",
    [4489] = "톱니항에 있는 스트라드 파선과 대화하십시오.",
    [4490] = "톱니항에 있는 스트라드 파선과 대화해 지옥마 소환 능력을 배워야 합니다.",
    [4701] = "검은바위 첨탑으로 가서 검은늑대 위협의 근원을 파괴해야 합니다. 헬렌디스를 떠날 때 헬렌디스가 오크들이 특정한 검은늑대를 부르는 말인 할리콘이라는 이름을 외치는 것을 들었습니다.",
    [4724] = "도끼부대 검은늑대 무리의 어미, 할리콘을 처치해야 합니다.",
    [4729] = "검은바위 첨탑으로 가서 새끼 도끼부대 검은늑대를 찾아야 합니다. 우리를 사용하여 이 사나운 야수들을 운반하여 키블러에게 사로잡은 새끼 검은늑대를 가져가야 합니다.",
    [4734] = "알껍질급속냉각기 견본을 둥지에 있는 알에 사용해야 합니다.",
    [4735] = "불타는 평원의 화염 마루에 있는 팅키 스팀보일에게 수집한 용의 알 8개를 가져가야 합니다.",
    [4742] = "사령관의 세 가지 보석인 가시불꽃부족 보석, 뾰족바위일족 보석, 도끼부대 보석을 찾아, 가공하지 않은 승천의 인장과 함께 밸란에게 가져가야 합니다.$B$B밸란이 말한 장군들은 가시불꽃부족의 대장군 부네, 뾰족바위일족의 대군주 오모크와 도끼부대의 대군주 웜타라크입니다.",
    [4743] = "먼지진흙 습지대에 있는 용의 둥지로 가서 고대 비룡, 엠버스트라이프를 찾아 그의 의지가 꺾일 때까지 무자비하게 공격을 펼쳐야 합니다.$B$B바로 그때 거대한 엠버스트라이프 앞에 벼려지지 않은 승천의 인장을 가져다 놓으십시오. 그리고 약해진 엠버스트라이프에게 재빨리 용력의 보주를 사용해 그의 정신력을 조종해야 합니다. 엠버스트라이프를 조종해 검은용군단의 화염을 벼려지지 않은 승천의 인장에 뿜어야 합니다!",
    [4764] = "불타는 평원에 있는 마야라 브라이트윙에게 파멸의 기념물을 가져가야 합니다.",
    [4765] = "스톰윈드에 있는 레밍턴 리지웰에게 리지웰의 상자를 가져가야 합니다.",
    [4766] = "불타는 평원에 있는 마야라 브라이트윙과 대화해야 합니다.",
    [4768] = "카르가스에 있는 어둠마법사 비비안 라그레이브에게 다크스톤 서판을 가져가야 합니다.",
    [4769] = "어둠마법사 비비안 라그레이브와 대화해야 합니다.",
    [4771] = "스칼로맨스의 스칼로맨스 강당 문에 여명의 계략을 놓아두고 벡투스를 처치한 후 베티나 비글징크에게 돌아가야 합니다.",
    [4787] = "고대의 알을 타나리스에 있는 예킨야에게 가져다주어야 합니다.",
    [4788] = "다섯 번째와 여섯 번째 모쉬아루 서판을 타나리스에 있는 발굴조사단장 아이언부트에게 갖다주어야 합니다.",
    [4862] = "검은바위 첨탑으로 가서 키블러를 위해 첨탑 거미알 15개를 수집해야 합니다.$B$B들리는 소문으로는 그 알들은 거미들이 서식하는 근처에서 찾을 수 있다고 합니다.",
    [4866] = "검은바위 첨탑 중심부에서 여왕 불그물거미를 찾을 수 있습니다. 여왕 불그물거미를 공격하거나 접근하여 그 독에 중독되어야 합니다. 독에 걸릴 확률을 높이기 위해서는 거미를 죽여야 할 수도 있습니다. 중독되면 털보 존에게 돌아가서 그가 그 독을 추출하게 해야 합니다.",
    [4867] = "와로쉬의 두루마리를 읽어야 합니다. 와로쉬에게 그의 부적을 가져가야 합니다.",
    [4903] = "대군주 오모크와 대장군 부네, 대군주 웜타라크를 처단해야 합니다. 검은바위의 중요한 문서들을 확보해야 합니다. 임무를 완수하는 대로 카르가스의 장군 고어투스에게로 돌아가야 합니다.",
    [4907] = "팅키 스팀보일과 대화해야 합니다.",
    [4921] = "크로스로드에 있는 만크릭을 위해 그의 아내의 흔적을 찾아 돌아가야 합니다.",
    [4941] = "오그리마의 스랄의 요새에 있는 아이트리그와 대화해야 합니다. 아이트리그의 얘기를 듣고 난 후에는 대족장 스랄과 상의해야 합니다.",
    [4974] = "검은바위 첨탑으로 가서 대족장 렌드 블랙핸드를 처치하십시오. 그 증거로 그의 머리카락을 가지고 오그리마로 돌아와야 합니다.",
    [4981] = "검은바위 첨탑으로 가서 비쥬에게 무슨 일이 생겼는지 알아봐야 합니다.",
    [4982] = "비쥬의 소지품을 찾아서 그녀에게 돌아가야 합니다. 비쥬가 도시의 바닥에 소지품을 숨겼다고 했습니다.",
    [4983] = "비쥬의 정찰 보고서를 가지고 카르가스의 렉스로트에게 가야 합니다.",
    [5001] = "비쥬의 소지품을 찾아 그녀에게 돌려줘야 합니다!",
    [5002] = "불타는 평원에 있는 치안대장 맥스웰에게 비쥬의 정보를 전해야 합니다.",
    [5047] = "눈망루 마을에 있는 말리퍼스 다크해머와 대화해야 합니다.",
    [5061] = "다르나서스로 돌아가 마스렌길 베어워커에게 바다표범의 펜던트를 보여 주어야 합니다.",
    [5065] = "세 번째와 네 번째 모쉬아루 서판을 찾아 타나리스에 있는 발굴조사단장 아이언부트에게 갖다주어야 합니다.",
    [5081] = "검은바위 첨탑으로 가서 대장군 부네와 대군주 오모크, 그리고 요새의 대군주 웜타라크를 처치해야 합니다. 임무를 완수하면 맥스웰 치안 대장에게 돌아가십시오.",
    [5089] = "불타는 평원에 있는 치안대장 맥스웰에게 사령관 드라키사스의 명령서를 가져가야 합니다.",
    [5096] = "펠스톤 농장과 달슨의 눈물 사이에 있는 붉은십자군의 야영지로 가서 지휘 막사를 파괴하십시오.$B$B기지에 스컬지 깃발을 세운 후, 서부 역병지대의 보루에 있는 고위집행관 델링턴에게 돌아가야 합니다.",
    [5097] = "신호 횃불로 안돌할의 각 탑을 표시해야 합니다. 성공적으로 표시하려면 탑의 입구에 서야 합니다.$B$B네 개의 감시탑에 모두 표시했으면 신호 횃불을 서부 역병지대의 서리바람 야영지에 있는 사령관 아쉬람 발러피스트에게 가져가십시오.",
    [5098] = "신호 횃불로 안돌할의 각 탑을 표시해야 합니다. 성공적으로 표시하려면 탑의 입구에 서야 합니다.$B$B네 개의 감시탑에 모두 표시했으면 신호 횃불을 서부 역병지대의 보루에 있는 고위집행관 델링턴에게 가져가십시오.",
    [5102] = "검은바위 첨탑으로 가서 사령관 드라키사스를 처치해야 합니다. 임무를 완수하면 치안대장 맥스웰에게 돌아가야 합니다.",
    [5122] = "난 이 교회의 힘으로 내 가슴 속의 타락에 저항하고 있소. 내가 이곳을 떠나면 죽음의 기사로 변해 버리게 될거요. 하지만 신념의 메달만 있으면 내가 이곳을 떠날 수 있는 힘을 줄 거요.$B$B부탁이니 그 메달을 가져다주시오. 그 메달은 광신자 말로가 지키고 있는데, 이 미친 녀석은 스트라솔름 서쪽에 있는 붉은십자군 성채에 사는 붉은십자군의 일원이라오.",
    [5125] = "난 죽어가지만... 내 영혼은 구제되었소. 당신에게 뭐라 말로 표현할 수 없는 신세를 진 거요. 부디 이걸 받아주시오. 그리고 계속 싸우시오, 용맹한 $C|1이여;여;!",
    [5127] = "검은바위 첨탑으로 가서 고랄루크 앤빌크랙을 찾아 처치한 후, 핏물이 깃든 창을 그의 심장에 꽂으십시오. 창이 그의 영혼을 흡수하면 영혼이 깃든 창으로 변합니다.$B$B벼려지지 않은 룬문자 흉갑도 찾아야 합니다.$B$B영혼이 깃든 창과 벼려지지 않은 룬문자 흉갑을 여명의 설원에 있는 로락스에게 갖다주십시오.",
    [5142] = "파멜라 레드패스를 찾아야 합니다.",
    [5149] = "파멜라의 인형을 찾아야 합니다.",
    [5152] = "안돌할 폐허 남쪽에서 말레네와 대화해야 합니다.",
    [5153] = "조셉의 결혼반지를 크로미에게 가져가야 합니다.",
    [5154] = "안돌할에 있는 다로우샤이어 연대기를 크로미에게 갖다주어야 합니다.",
    [5160] = "여명의 설원으로 가서 헬레를 찾아 그녀에게 아우비의 비늘을 전해야 합니다.",
    [5163] = "우미의 기계설인을 가지고 가서 아래 친구들에게 겁을 주어야 합니다.$B$B여명의 설원, 눈망루 마을에 있는 레각키$B타나리스의 가젯잔에 있는 스프링클$B운고로 분화구, 마샬의 야영지에 있는 퀵실$B$B모두에게 겁을 주고 나서 기계설인을 도로 우미에게 데리고 가야 합니다.",
    [5168] = "카를린 레드패스에게 다빌의 성서와 레드패스의 방패를 가져가야 합니다.",
    [5181] = "희망의 빛 예배당에 있는 카를린 레드패스에게 호르구스의 해골과 부러진 마르두크의 검을 가져가야 합니다.",
    [5206] = "동부 역병지대에 있는 카를린 레드패스에게 텅빈 해골 5개와 불가사의한 수정을 가져가야 합니다.",
    [5210] = "동부 역병지대에 있는 카를린 레드패스에게 확장된 다로우샤이어 연대기를 가져가야 합니다.",
    [5211] = "15명의 다로우샤이어 주민들의 원혼을 자유롭게 하고 카를린 레드패스에게 돌아가야 합니다.",
    [5212] = "스트라솔름에서 20개의 역병걸린 살덩어리 견본을 베티나 비글징크에게 가져다주어야 합니다. 스트라솔름의 어떤 생물에서든 살덩어리 견본을 구할 수 있을 것 같습니다.",
    [5213] = "스트라솔름으로 가서 지구라트를 조사해야 합니다. 스컬지 자료를 찾아 베티나 비글징크에게 돌아가야 합니다.",
    [5214] = "스트라솔름에서 에즈라 그림의 최고급 담배를 회수하여 스모키 라루에게 가져가야 합니다.",
    [5241] = "카를린 레드패스를 찾아야 합니다.",
    [5243] = "북쪽에 있는 스트라솔름으로 가서 도시 어딘가에 흩어진 보급품 상자를 찾아 스트라솔름 성수 5병을 가져와야 합니다. 성수를 충분히 모으고 나면 존경받는 리어니드 바돌로매에게 돌아가야 합니다.",
    [5251] = "스트라솔름으로 가서 붉은십자군의 기록관, 갈포드를 찾아서 그를 처치하고 붉은십자군 기록을 불태워 버려야 합니다.",
    [5262] = "동부 역병지대에 있는 공작 니콜라스 즈바른호프에게 발나자르의 혼을 가져가야 합니다.",
    [5263] = "스트라솔름으로 가서 남작 리븐데어를 처치하고 그의 혼을 공작 니콜라스 즈바른호프에게 가져가야 합니다.",
    [5282] = "스트라솔름 시민의 영혼과 원혼들에게 에간의 제령포를 사용해야 합니다. 원혼들이 그들을 가두고 있던 감옥에서 풀려나면 다시 총을 사용하여 그들에게 자유를 선사하십시오!$B$B15명의 잠 못드는 영혼을 자유롭게 하고 에간에게 돌아가야 합니다.",
    [5341] = "스칼로맨스로 가서 바로브 가의 유산을 회수해야 합니다. 이 재산은 카엘 다로우 증서, 브릴 증서, 타렌 밀농장 증서, 사우스쇼어 증서의 4개 땅문서로 이루어져 있습니다. 임무를 완수한 후 알렉시 바로브에게 돌아가야 합니다.",
    [5342] = "얼라이언스 영토인 서리바람 야영지로 가서 웰던 바로브를 암살해야 합니다. 그 증거로 그의 머리카락을 가지고 알렉시 바로브에게 돌아가십시오.$B$B얼라이언스 쓰레기들이 웰던을 보호하고 있을 테니 조심해야 합니다.",
    [5343] = "스칼로맨스로 가서 바로브 가의 유산을 회수해야 합니다. 이 유산은 카엘 다로우 증서, 브릴 증서, 타렌 밀농장 증서, 사우스쇼어 증서의 4개 땅문서로 이루어져 있습니다. 이 임무를 완수한 후 웰던 바로브에게 돌아가야 합니다.",
    [5344] = "호드의 영토인 보루로 가서 알렉시 바로브를 암살하십시오. 그 증거로 그의 머리카락을 가지고 웰던 바로브에게 돌아가십시오.$B$B더러운 호드가 알렉시를 보호하고 있을 테니 조심해야 합니다.",
    [5382] = "스칼로맨스 내에서 학자 테올렌 크라스티노브를 찾아 처치한 후 에바 사크호프의 유해와 루시엔 사크호프의 유해를 불태우십시오. 임무를 완수하면 에바 사크호프에게 돌아가야 합니다.",
    [5383] = "소름끼치는 크라스티노브의 가방을 카엘 다로우에 있는 에바 사크호프에게 가져가야 합니다.",
    [5384] = "순결한 피를 가지고 스칼로맨스로 돌아가야 합니다. 사자의 창을 찾아 사자의 화롯불에 순결한 피를 올려 놓으면 키르토노스가 영혼을 차지하기 위해 나타납니다.$B$B용맹하게 싸우고 단 한 발짝도 물러서지 마십시오! 키르토노스를 처치한 후 에바 사크호프에게 돌아가야 합니다.",
    [5461] = "아라시 고원에 있는 스트롬가드 폐허로 가십시오. 스트롬가드에서 추억의 유품을 찾아야 합니다. 그런 물건을 찾으면 집정관 마르듀크에게 돌아가야 합니다.",
    [5462] = "동부 역병지대에 있는 희망의 빛 예배당으로 가서 존경받는 리어니드 바돌로매를 찾아서 추억의 유품을 보여 주고 알아낸 사실에 대해 모두 얘기해야 합니다.",
    [5463] = "스트라솔름으로 가서 메네실의 선물을 찾아서 그 부정한 땅 위에 추억의 유품을 두어야 합니다.",
    [5464] = "동부 역병지대에 있는 리어니드 바돌로매에게 영혼이 씌인 유품을 가져가야 합니다.",
    [5465] = "카엘 다로우에 있는 집정관 마르듀크에게 돌아가십시오. 그에게 영혼이 씌인 유품을 보여줘야 합니다.",
    [5466] = "스칼로맨스에서 라스 프로스트위스퍼를 찾아야 합니다. 영혼이 쓰인 유품을 언데드 상태인 라스의 얼굴에 사용하십시오. 그를 산 자로 되돌리는 데 성공하면 그를 쓰러뜨리고 사람이 된 라스 프로스트위스퍼의 머리카락을 가지고 집정관 마르듀크에게 가야 합니다.",
    [5514] = "가젯잔에 있는 크린클 굿스틸에게 15골드와 함께 마력 깃든 뼈조각을 가져가야 합니다.",
    [5515] = "스칼로맨스에서 잔다이스 바로브를 찾아 처치해야 합니다. 그녀의 시체에서 소름끼치는 크라스티노브의 가방을 찾은 후 에바 사크호프에게 가져가야 합니다.",
    [5518] = "룬무늬 두루마리 4개, 튼튼한 가죽 8장, 룬문자 실타래 2개, 그리고 오우거 타닌을 노트 팀블잭에게 가져가야 합니다. 노트 팀블잭은 혈투의 전장에 있는 고르독일족 은신처 구석에 족쇄에 묶여 있습니다.",
    [5525] = "그건 고르독 족쇄 열쇠라고 하는 물건이지. 이 오우거 얼간이들이 그렇게 부르더군. 이곳 오우거들이라면 누구나 지니고 있을 텐데, 어떤 오우거 녀석들이 지니고 있는지는 모르겠단 말이야. 경비병들이라면 갖고 있을 확률이 더 높겠지...$B$B아니, 내가 지금 뭔 소리 하는 거야. 당신 벌써 그 열쇠 갖고 있지?! 그게 바로 그 열쇠야?!",
    [5528] = "힉... 이제 당신 우리 대빵이니까 좀 괜찮은 술 하나 맛볼 수 있다! 힉... 이 술 마시면 기운 나고 기분도 아주 좋아진다! 힉... 이게 알짜배기 술이야, 왕... 한번 마시고 크리그에게 어떤지 말해줘... 힉!",
    [5529] = "역병 걸린 작은 새끼용 20마리를 처치한 후 희망의 빛 예배당에 있는 베티나 비글징크에게 돌아가야 합니다.",
    [5531] = "베티나 비글징크에게 얼어붙은 알을 가져가야 합니다.",
    [5533] = "서부 역병지대의 서리바람 거점에 있는 연금술사 알빙턴과 대화해야 합니다.",
    [5537] = "서부 역병지대에 서리바람 거점에 있는 연금술사 알빙턴에게 뼈조각 15개를 가져가야 합니다.",
    [5538] = "가젯잔에 있는 크린클 굿스틸에게 15골드를 지급하고 마력 깃든 뼈조각을 가져가야 합니다.",
    [5582] = "동부 역병지대의 희망의 빛 예배당에 있는 베티나 비글징크에게 생기 있는 용비늘을 가져가야 합니다.",
    [5601] = "다로우샤이어에서 파멜라 레드패스를 찾아야 합니다.",
    [5721] = "다로우샤이어 마을 광장에 유물 더미를 가져다 놓아야 합니다.$B$B호르구스보다 다빌 라이트파이어가 먼저 죽지 않도록 다빌을 보호해야 합니다.$B$B레드패스는 오염되기 전까지 처치하면 안 됩니다.$B$B레드패스가 오염되면 처치해야 합니다.$B$B마을 광장에 조셉 레드패스의 영혼이 나타나면 대화를 나눈 후 집에 있는 파멜라와 대화를 나누십시오.",
    [5742] = "티리온 폴드링이 하려고 하는 말이 무엇인지 들어야 합니다.",
    [5762] = "가시덤불 골짜기에 있는 헤멧 네싱워리에게 크레이블의 상자를 가져가야 합니다.",
    [5763] = "가시덤불 골짜기에 있는 헤멧 네싱워리에게 룬의 코도 뿔을 가져가야 합니다.",
    [5781] = "동부 역병지대의 최남쪽에 있는 지하 납골당으로 가서 탤런의 망치를 되찾은 후 티리온 폴드링에게 돌아가서 임무를 완수해야 합니다.",
    [5801] = "운고로 분화구에 있는 불기둥 마루의 꼭대기로 해골 열쇠 거푸집과 토륨 주괴 2개를 가져가야 합니다. 용암의 강에서 해골 열쇠 거푸집을 이용해서 불완전한 해골 열쇠를 만들어야 합니다.$B$B불완전한 해골 열쇠를 서부 역병지대의 서리바람 거점에 있는 연금술사 알빙턴에게 가져가야 합니다.",
    [5802] = "운고로 분화구에 있는 불기둥 마루 꼭대기로 해골 열쇠 거푸집과 토륨 주괴 2개를 가져가야 합니다. 용암의 강에서 해골 열쇠 거푸집으로 불완전한 해골 열쇠를 만들어야 합니다.$B$B불완전한 해골 열쇠를 서부 역병지대의 보루에 있는 연금술사 디더스에게 가져가야 합니다.",
    [5803] = "소환사 아라즈를 처치하고 아라즈의 스카라베를 서부 역병지대의 서리바람 거점에 있는 연금술사 알빙턴에게 돌아가야 합니다.",
    [5804] = "소환사 아라즈를 처치하고 아라즈의 스카라베를 서부 역병지대에 보루에 있는 연금술사 디더스에게 돌아가야 합니다.",
    [5845] = "동부 역병지대의 북동쪽에 있는 노스데일로 가서 실추된 명예의 상징을 되찾은 후 티리온 폴드링에게 돌아가서 임무를 완수해야 합니다.",
    [5846] = "역병지대의 남쪽 중앙에 있는 카엘 다로우로 가서 초상화가 어디쯤 있는지에 대한 단서를 찾아야 합니다.",
    [5848] = "역병지대의 북쪽, 스트라솔름에 있는 붉은십자군 성채로 가서 쌍둥이 달 그림을 찾으십시오.$B$B그 뒤에 숨겨진 '가족과 사랑'이라는 그림을 찾아 티리온 폴드링에게 가져가야 합니다.",
    [5861] = "역병지대의 남쪽에 위치한 우서 경의 무덤으로 가서 티리온의 선물을 노파 미란다에게 보여줘야 합니다.",
    [5862] = "붉은십자군 환영을 얻어 노파 미란다와 대화해야 합니다. 붉은십자군 환영을 보유하고 있는 동안 하스글렌으로 가서 티리온의 선물을 대영주 탤런 폴드링에게 전해야 합니다.$B$B하스글렌은 북쪽에 있으며 탤런은 마르덴홀드 요새 내부에서 찾을 수 있을 겁니다.",
    [5921] = "\"순간이동: 달의 숲\" 주문을 이용하여 달의 숲으로 이동하십시오. 도착하면 나이트헤이븐의 덴드리트 스타블레이즈와 대화해야 합니다.",
    [5922] = "\"순간이동: 달의 숲\" 주문을 이용하여 달의 숲으로 이동해야 합니다. 달의 숲에 도착하면 나이트헤이븐의 덴드리트 스타블레이즈와 대화해야 합니다.",
    [5923] = "다르나서스 세나리온 자치령에 있는 마스렌길 베어워커와 대화해야 합니다.",
    [5924] = "다르나서스 세나리온 자치령에 있는 마스렌길 베어워커와 대화해야 합니다.",
    [5925] = "다르나서스 세나리온 자치령에 있는 마스렌길 베어워커와 대화해야 합니다.",
    [5926] = "썬더 블러프의 장로의 봉우리에 있는 투락 룬토템과 대화해야 합니다.",
    [5927] = "썬더 블러프 장로의 봉우리에 있는 투락 룬토템과 대화해야 합니다.",
    [5928] = "썬더 블러프의 장로의 봉우리에 있는 투락 룬토템과 대화해야 합니다.",
    [5929] = "달의 숲 북서쪽에 사는 거대한 곰의 혼을 찾아가 드루이드라면 반드시 알아야 할 곰의 본성에 대해 배워야 합니다. 임무를 완수하면 달의 숲, 나이트헤이븐에 있는 덴드리트 스타블레이즈에게 돌아가십시오.",
    [5930] = "달의 숲 북서쪽에 사는 거대한 곰의 혼을 찾아가 드루이드라면 반드시 알아야 할 곰의 본성에 대해 배워야 합니다. 임무를 완수하면 달의 숲, 나이트헤이븐에 있는 덴드리트 스타블레이즈에게 돌아가십시오.",
    [5931] = "다르나서스로 돌아가 세나리온 자치령에 있는 마스렌길 베어워커와 대화해야 합니다.",
    [5932] = "썬더 블러프로 돌아가 장로의 봉우리에 있는 투락 룬토템과 대화해야 합니다.",
    [5941] = "안돌할의 크로미에게 유물 자루를 가져가야 합니다.",
    [5942] = "조셉의 상자가 있는 곳으로 조셉의 열쇠를 가져가야 합니다.",
    [5944] = "탤런 폴드링을 하스글렌 밖으로 호위해야 합니다.",
    [6001] = "아우버다인의 달빛야수 비석에 세나리온 달가루를 뿌려서 초승달발톱을 불러내야 합니다. 그런 다음 초승달발톱과 대면하여 그가 가진 육체와 정신의 힘을 얻어야 합니다.$B$B모든 일을 마치면 다르나서스에 있는 마스렌길 베어워커와 대화하십시오.",
    [6002] = "초승달발톱을 불러내려면 멀고어와 불모의 땅 사이에 있는 달빛야수 비석에 세나리온 달가루를 사용해야 합니다. 거기에서 초승달발톱과 대적하여 그가 가진 육체와 마음의 힘을 얻으십시오.$B$B임무를 마치면 썬더 블러프에 있는 투락 룬토템과 대화해야 합니다.",
    [6004] = "붉은십자군 의무병 2명, 붉은십자군 사냥꾼 2명, 붉은십자군 마법사 2명, 붉은십자군 기사 2명을 처치하고 서부 역병지대에 있는 키르스타 딥섀도에게 돌아가야 합니다.",
