    [6102] = "조련용 막대를 사용해 비명소리 스트리기드 올빼미를 길들여야 합니다. 기술을 연습한 후 돌라나르에 있는 다잘라에게 조련용 막대를 돌려주어야 합니다.",
    [6103] = "다르나서스의 세나리온 자치령에서 조카스테와 대화하십시오.",
    [6121] = "달의 숲으로 가서 나이트헤이븐 마을에 있는 덴드리트 스타블레이즈와 대화해야 합니다.",
    [6122] = "빈 절벽 폭포 견본병을 이용해 폭포 옆에 있는 동굴 입구에서 물을 채취해야 합니다.$B$B물을 다 채우면, 아우버다인, 어둠의 해안에 있는 알란다리안 나이트송에게 가득 찬 절벽 폭포 견본병을 갖다주어야 합니다.",
    [6123] = "아우버다인의 알란다리안 나이트송이 치료제를 만들 수 있도록 뱀뿌리 5개와 달버섯 12개를 가져다 주어야 합니다.",
    [6124] = "어둠의 해안에 퍼져 있는 병든 사슴 10 마리에게 잘 듣는 동물 연고를 발라 치료해야 합니다. 병든 사슴은 폭포수 강 남부에서 아우버다인 북부까지 퍼져 있으며 잿빛 골짜기가 시작되는 어둠의 해안 남부까지 넘나든다고 합니다.",
    [6125] = "다르나서스, 세나리온 자치령에 있는 마스렌길 베어워커에게 돌아가야 합니다.",
    [6126] = "달의 숲으로 가서 나이트헤이븐 마을에 있는 덴드리트 스타블레이즈와 대화해야 합니다.",
    [6127] = "빈 공포의 안개봉우리 견본병을 봉우리 정상까지 가지고 가서 꼭대기 물웅덩이의 물을 채취해야 합니다.$B$B가득 찬 공포의 안개봉우리 견본병을 불모의 땅, 크로스로드에 있는 통가 룬토템에게 갖다주어야 합니다.",
    [6128] = "크로스로드의 통가 룬토템이 치료제를 만들 수 있도록 뱀뿌리 5개와 코도 뿔 5개를 갖다주어야 합니다.",
    [6129] = "불모의 땅 북부에 퍼져 있는 병든 가젤 10마리를 찾아 잘 듣는 동물 연고를 발라서 치료해야 합니다. 병든 가젤은 크로스로드를 동서로 가로지르는 길의 북쪽에 있다고 합니다.",
    [6130] = "썬더 블러프 장로의 봉우리에 있는 투락 룬토템에게 돌아가야 합니다.",
    [6141] = "잊혀진 땅에 있는 수사 안톤과 대화해야 합니다.",
    [6144] = "언더시티로 가서 바리마트라스와 대화해야 합니다.",
    [6145] = "동부 역병지대로 돌아가 진홍십자군 급사를 추적해야 합니다. 급사를 처치하고 십자군 사령관의 명령서를 회수해야 합니다.$B$B이 명령서를 나타노스 블라이트콜러에게 가져다주고 다음 지시를 받으십시오.",
    [6146] = "마리스 농장 남동쪽에 있는 티르의 손 수도원으로 간 다음, 그곳에서 썩은 사과를 한 입 먹어야 합니다. 붉은십자군의 모습을 한 채로 십자군군주 발델마르에게 십자군 사령관의 명령서를 가져가야 합니다.",
    [6147] = "이 새로운 정보를 가지고 나타노스 블라이트콜러에게 돌아가야 합니다.",
    [6148] = "붉은십자군 예언가가 이동하고 있습니다. 티르의 손 수도원에서 스트라솔름으로 가는 길 어딘가에서 예언가인 데메트리아와 그녀의 호위병들을 찾을 수 있을 것입니다. 그녀를 추적해서 처치하고 성공하면 나타노스 블라이트콜러에게 돌아가야 합니다.",
    [6163] = "스트라솔름으로 가서 먹보 람스타인을 처치하고 그 증거로 그의 머리카락을 나타노스에게 가져가야 합니다.",
    [6402] = "스톰윈드 도시 성문으로 가서, 수습기사 로우와 대화하면 그가 당신의 도착을 치안대장 윈저에게 알릴 것입니다.",
    [6403] = "레지널드 윈저를 따라 스톰윈드를 통과해 왕궁으로 가야 합니다. 윈저를 보호하십시오!",
    [6501] = "전 세계를 뒤져 용의눈 조각의 힘을 복원할 수 있는 자를 찾아야 합니다. 이와 관련해 알고 있는 유일한 정보는 그러한 자들이 존재한다는 것뿐입니다.",
    [6502] = "사령관 드라키사스에게서 검은용 용사의 피를 가져와야 합니다.",
    [6566] = "스랄의 이야기를 들어야 합니다.",
    [6567] = "렉사르를 찾아야 합니다. 그의 행방은 대족장이 설명해 주었습니다. 돌발톱 산맥과 페랄라스 사이에 있는 잊혀진 땅의 길에서 찾아 보십시오.",
    [6568] = "서부 역병지대에 있는 노파 미란다에게 렉사르의 유서를 전달해야 합니다.",
    [6569] = "검은바위 첨탑으로 가서 검은 용혈족의 눈동자 20개를 모아서 노파 미란다에게 돌아가야 합니다.",
    [6570] = "먼지진흙 습지대에 있는 용의 둥지로 가서 엠버스트라이프의 굴을 찾아야 합니다. 안으로 들어가서 용족 파멸의 아뮬렛을 착용하고 엠버스트라이프와 대화해야 합니다.",
    [6582] = "여명의 설원에서 찾을 수 있는 푸른용군단의 용사 스크라이어를 찾아 처치해야 합니다. 그의 시체에서 해골을 수습해서 엠버스트라이프에게 돌아가야 합니다.",
    [6583] = "녹색용군단의 우두머리 솜누스를 처치한 후 그의 해골을 수습해서 엠버스트라이프에게 돌아가야 합니다.",
    [6584] = "노즈도르무의 자손인 크로날리스가 타나리스 사막에 있는 시간의 동굴을 지키고 있습니다. 그를 처치한 후 그의 해골을 엠버스트라이프에게 가져가야 합니다.",
    [6585] = "그림 바톨로 가서 붉은용군단의 우두머리 악트로즈를 찾아 그를 처치한 다음 그의 해골을 수습하여 엠버스트라이프에게 돌아가야 합니다.",
    [6601] = "이제 가면놀이는 끝난 것 같습니다. 노파 미란다가 만든 용족 파멸의 아뮬렛이 검은바위 첨탐 안에서 원래 구실을 하지 않는 것을 알고 있습니다. 아마도 렉사르를 찾아가 곤경에 처한 상황을 설명하는 것이 좋겠습니다. 렉사르에게 흐릿한 비룡불꽃 아뮬렛을 보여주면 아마도 필요한 게 무엇인지 알 수 있을 겁니다.",
    [6602] = "검은바위 첨탑으로 가서 사령관 드라키사스를 처치하고 사령관의 피를 모아 렉사르에게 가져가야 합니다.",
    [6681] = "힐스브래드의 구릉지에 숨어 있는 라벤홀트 장원의 파라드에게 라벤홀트의 인장을 가져가야 합니다.$B$B라벤홀트 장원의 입구 근처에서 자신의 실력을 증명할 상자를 발견하게 될 것이며 어떤 기술을 사용하여 이를 증명해야 할지 준비해야 합니다.",
    [6721] = "돌라나르에 있는 다잘라와 대화하십시오.",
    [6722] = "돌라나르에 있는 다잘라와 대화하십시오.",
    [6981] = "톱니항으로 가서 빛나는 조각에 대해 자세히 얘기해 줄 수 있는 이를 찾으십시오.$B$B그에게 지시를 받아, 빛나는 조각을 전달해야 합니다.",
    [7028] = "트라드릭 수정 조각상 25개를 모아서 잊혀진 땅에 있는 윌로우에게 가져가야 합니다.",
    [7029] = "마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다.$B$B오염된 녹시온의 후예가 나타나게 하려면 바일줄기 덩굴나무 위에 감청색 약병에 담긴 액체를 부어야 합니다.$B$B녹시온의 후예를 죽이는 방법으로 8개의 식물을 치료한 다음 그늘수렵 마을에 있는 바르크 배틀스카에게 돌아가야 합니다.",
    [7041] = "마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다.$B$B오염된 녹시온의 후예가 나타나게 하려면 바일줄기 덩굴나무 위에 감청색 약병에 담긴 액체를 부어야 합니다.$B$B녹시온의 후예를 죽이는 방법으로 8개의 식물을 치료한 다음 나이젤의 야영지에 있는 탈렌드리아에게 돌아가야 합니다.",
    [7044] = "셀레브라스의 홀 조각인 셀레브리안 마법봉과 셀레브리안 다이아몬드를 찾아야 합니다.$B$B셀레브라스와 대화를 나눌 방법을 찾아야 합니다.",
    [7046] = "회복된 셀레브라스가 셀레브라스의 홀을 만드는 동안 그를 도와야 합니다.$B$B의식을 마친 후 그와 대화하십시오.",
    [7064] = "공주 테라드라스를 해치우고 잊혀진 땅의 그늘수렵 마을 근처에 있는 셀렌드라에게 돌아가야 합니다.",
    [7065] = "공주 테라드라스를 해치우고 잊혀진 땅의 나이젤의 야영지에 있는 수호자 마란디스를 찾아가야 합니다.",
    [7066] = "달의 숲에 있는 수호자 레물로스를 찾아 생명의 씨앗을 전해 주어야 합니다.",
    [7067] = "추방자의 지시서를 읽은 다음 마라우돈에서 결속의 아뮬렛을 획득해서 잊혀진 땅 남부에 있는 켄타우로스 추방자에게 가져가야 합니다.",
    [7068] = "마라우돈에서 음영석 조각 10개를 모아서 오그리마에 있는 우텔나이에게 가져가야 합니다.",
    [7070] = "마라우돈에서 음영석 조각 10개를 모아서 먼지진흙 습지대의 해안에 위치한 테라모어에 있는 대마법사 테르보쉬에게 가져가야 합니다.",
    [7201] = "검은바위 나락으로 가서 원소의 정수 10개를 회수해야 합니다. 먼저 골렘이나 골렘 제조자부터 찾아보십시오. 비비안 라그레이브가 정령에 대해 중얼거리듯 얘기한 것이 기억납니다.",
    [7441] = "혈투의 전장으로 가서 푸실린이라는 임프를 찾으십시오. 어떤 수단을 써서라도 아즈토리딘의 마법서를 돌려받아야 합니다.$B$B마법서를 회수하면 페랄라스의 라리스 정자에 있는 아즈토리딘에게 돌아가야 합니다.",
    [7461] = "이몰타르의 감옥에 힘을 공급하는 다섯 개의 수정탑을 둘러싼 수호자들을 처치해야 합니다. 수정탑의 마력이 약해지면 이몰타르를 둘러싼 마법진도 분산될 것입니다.$B$B이몰타르의 감옥에 들어가 그 심장부에 서 있는 사악한 이몰타르를 처치하고, 마지막으로 도서관에 있는 토르텔드린 왕자와 맞서 싸우십시오.$B$B이 임무를 완수하면 안마당에 있는 셴드랄라 고대인에게 돌아가야 합니다.",
    [7462] = "도서관으로 되돌아가 셴드랄라의 보물을 찾아야 합니다. 임무 완수에 대한 보상을 받으십시오!",
    [7463] = "혈투의 전장에 있는 굽이나무 지구로 가서 물의 정령인 히드로스폰을 처치하십시오. 히드로스폰의 정수를 가지고 도서관에 있는 현자 리드로스에게 돌아가야 합니다.",
    [7481] = "혈투의 전장을 뒤져 텔미우스 드림시커를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 모자케 야영지에 있는 현자 코로루스크에게 돌아가야 합니다.",
    [7482] = "혈투의 전장을 뒤져 텔미우스 드림시커를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 페더문 요새에 있는 학자 룬쏜에게 돌아가야 합니다.",
    [7488] = "페랄라스의 페더문 요새에 있는 라트로니쿠스 문스피어에게 레스텐드리스의 그물을 가져가야 합니다.",
    [7489] = "페랄라스의 모자케 야영지에 있는 탈로 쏜후프에게 레스텐드리스의 그물을 가져가야 합니다.",
    [7490] = "오그리마에 있는 대족장 스랄에게 오닉시아의 머리를 보여줘야 합니다.",
    [7491] = "힘의 골짜기에서 대군주 룬탁을 찾으십시오.",
    [7492] = "페랄라스의 모자케 야영지에 있는 탈로 쏜후프와 대화하십시오.",
    [7493] = "용을 처치한 데다 숙련된 가죽세공사라고요? 당신은 정말 끝없이 저를 놀라게 하는군요, 영웅이여. 고개가 절로 숙여집니다.$B$B제가 지금부터 가르쳐 드릴 것을 부디 받아 주십시오. 검은용군단의 잔당을 쓸어버리려 한다면 이 지식은 더없이 귀중하게 쓰일 것입니다.$B$B용의 어미의 비늘로 망토를 만드십시오. 그 망토가 검은바위의 군주... 네파리안의 불타는 숨결로부터 당신과 동료들을 지켜 줄 것입니다.",
    [7494] = "페랄라스의 페더문 요새에 있는 라트로니쿠스 문스피어와 대화하십시오.",
    [7495] = "오닉시아의 머리를 스톰윈드로 갖고 가서 대영주 볼바르 폴드라곤에게 보여주어야 합니다.",
    [7496] = "영웅의 계곡에서 상사 매팅글리를 찾으십시오.",
    [7497] = "용을 처치한 데다 숙련된 가죽세공사라고요? 당신은 정말 끝없이 저를 놀라게 하는군요, 영웅이여. 고개가 절로 숙여집니다.$B$B제가 지금부터 가르쳐 드릴 것을 부디 받아 주십시오. 검은용군단의 잔당을 쓸어버리려 한다면 이 지식은 더없이 귀중하게 쓰일 것입니다.$B$B용의 어미의 비늘로 망토를 만드십시오. 그 망토가 검은바위의 군주... 네파리안의 불타는 숨결로부터 당신과 동료들을 지켜 줄 것입니다.",
