    [97179] = "힐스브래드 구릉지에 있는 오트에게 룬매듭 옷감 40개, 아케이나이트 주괴 6개, 아서스의 눈물 10개, 스트라솔름 성수 5병, 150골드를 가져가야 합니다.",
    [97180] = "검사를 받기 위해 반다리온 성채에 있는 다니타 모르에게 아케이나이트 마갑을 가져가야 합니다.",
    [97182] = "영혼의 말에게 먹이는 특제 말 사료를 구해야 합니다. 동부 역병지대에 있는 나타노스 블라이트콜러가 그런 사료를 구해 줄 수 있을지도 모릅니다.$B$B페랄라스에 있는 혈투의 전장으로 가서 텐드리스 워프우드를 처치해야 합니다. 그러면 고대 준마의 영혼이 풀려날 것입니다. 특제 말 사료를 먹여 영혼을 진정시켜야 합니다.$B$B마지막으로 아케이나이트 마갑을 건네고 영혼이 필요한 축복을 내려 주기를 바라야 합니다.",
    [97183] = "축복받은 아케이나이트 마갑을 가지고 티리스팔 숲의 반다리온 성채에 있는 다니타 모르에게 돌아가야 합니다.",
    [97184] = "티리스팔 숲의 반다리온 성채에 있는 다니타 모르에게 아제로스 다이아몬드와 흠 없는 검은 다이아몬드를 가져가야 합니다.",
    [97185] = "스칼로맨스에 있는 대납골당 지하 한가운데에서 예언의 탐지기를 사용하십시오. 그러면 심판해야 할 영혼들이 나타납니다. 이 영혼들을 물리치면 죽음의 기사 다크리버가 소환됩니다. 그를 처치하고 쓰러진 군마의 잃어버린 영혼을 되찾아야 합니다.$B$B응징의 영혼과 축복받은 마법 마갑을 다크리버의 쓰러진 군마에게 건네야 합니다.",
    [97186] = "동부 역병지대에 있는 나타노스 블라이트콜러를 위해 영양 강화 만나 비스킷 20개를 구해야 합니다. 이 비스킷은 은빛 여명회만 공급하는 것으로 알려져 있습니다. 또한 블라이트콜러에게 수고비로 50골드를 지불해야 합니다.",
    [97197] = "검은바위 나락에서 불의 땅의 파편을 회수해 멀고어에 있는 알라나 스톰워커에게 전달해야 합니다.",
